import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";

export default function EditDeliveryForm() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [form, setForm] = useState({
    customerId: "",
    status: "",
    lat: "",
    lng: "",
  });

  useEffect(() => {
    axios.get(`http://localhost:5000/api/delivery/get/${id}`).then((res) => {
      const delivery = res.data[0]; // assuming backend returns array
      setForm({
        customerId: delivery.customerId,
        status: delivery.status,
        lat: delivery.location.lat,
        lng: delivery.location.lng,
      });
    });
  }, [id]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await axios.put(`http://localhost:5000/api/delivery/${id}`, {
        customerId: form.customerId,
        status: form.status,
        location: {
          lat: parseFloat(form.lat),
          lng: parseFloat(form.lng),
        },
      });
      alert("✅ Delivery updated!");
      navigate("/");
    } catch (err) {
      alert("❌ Update failed");
    }
  };

  return (
    <form onSubmit={handleUpdate} style={{ padding: "20px", maxWidth: "400px", margin: "auto" }}>
      <h2>Edit Delivery</h2>
      <input
        name="customerId"
        value={form.customerId}
        onChange={handleChange}
        placeholder="Customer ID"
        required
        style={{ width: "100%", marginBottom: "10px", padding: "8px" }}
      />
      <input
        name="lat"
        value={form.lat}
        onChange={handleChange}
        placeholder="Latitude"
        required
        style={{ width: "100%", marginBottom: "10px", padding: "8px" }}
      />
      <input
        name="lng"
        value={form.lng}
        onChange={handleChange}
        placeholder="Longitude"
        required
        style={{ width: "100%", marginBottom: "10px", padding: "8px" }}
      />
      <select
        name="status"
        value={form.status}
        onChange={handleChange}
        style={{ width: "100%", marginBottom: "10px", padding: "8px" }}
      >
        <option value="Assigned">Assigned</option>
        <option value="Pending">Pending</option>
        <option value="In Transit">In Transit</option>
        <option value="Delivered">Delivered</option>
      </select>
      <button type="submit" style={{ padding: "10px 20px" }}>
        Update Delivery
      </button>
      <button
        type="button"
        onClick={() => navigate("/")}
        style={{
          padding: "10px 20px",
          marginLeft: "10px",
          backgroundColor: "#6c757d",
          color: "#fff",
          border: "none",
          borderRadius: "4px",
        }}
      >
        ← Back
      </button>
    </form>
  );
}
